SELECT ora.id, ora.order_id, o.order_no, ora.refund_no, ora.refund_type, ora.apply_amount, ora.apply_reason, ora.status, CASE WHEN ora.status = 'PENDING' THEN '待审核' WHEN ora.status = 'APPROVED' THEN '已通过' WHEN ora.status = 'REJECTED' THEN '已拒绝' WHEN ora.status = 'REFUNDED' THEN '已退款' ELSE '未知状态' END as status_description, ora.audit_remark, ora.audit_time, ora.refund_time, ora.created_time, ora.updated_time, o.merchant_id, o.store_id FROM order_refund_applies ora LEFT JOIN orders o ON ora.order_id = o.id WHERE ora.is_deleted = 0
AND ora.order_id = #{query.orderId}
AND o.order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND ora.refund_no LIKE CONCAT('%', #{query.refundNo}, '%')
AND ora.status = #{query.status}
AND ora.refund_type = #{query.refundType}
AND ora.created_time >= #{query.startTime}
AND ora.created_time <= #{query.endTime}
ORDER BY ora.created_time DESC

