SELECT ora.id, ora.order_id, o.order_no, ora.refund_no, ora.refund_type, ora.apply_amount, ora.apply_reason, ora.status, CASE WHEN ora.status = 'PENDING' THEN '待审核' WHEN ora.status = 'APPROVED' THEN '已通过' WHEN ora.status = 'REJECTED' THEN '已拒绝' WHEN ora.status = 'REFUNDED' THEN '已退款' ELSE '未知状态' END as status_description, ora.audit_remark, ora.audit_time, ora.refund_time, ora.created_time, ora.updated_time, o.user_id FROM order_refund_applies ora LEFT JOIN orders o ON ora.order_id = o.id WHERE ora.is_deleted = 0
